use std::cell::RefCell;
use std::rc::{Rc, Weak};

#[derive(Debug)]
pub struct BOSTree {
    pub root_node: Option<Rc<RefCell<BOSNode>>>,
    pub cmp_function: BOSTreeCmpFunction,
    pub free_function: Option<BOSTreeFreeFunction>,
}

#[derive(Debug)]
pub struct BOSNode {
    pub left_child_count: u32,
    pub right_child_count: u32,
    pub depth: u32,
    pub left_child_node: Option<Rc<RefCell<BOSNode>>>,
    pub right_child_node: Option<Rc<RefCell<BOSNode>>>,
    pub parent_node: Option<Weak<RefCell<BOSNode>>>,
    pub key: String,
    pub data: Option<String>,
    pub weak_ref_count: u8,
    pub weak_ref_node_valid: u8,
}

pub type BOSTreeCmpFunction = fn(&str, &str) -> i32;
pub type BOSTreeFreeFunction = fn(&Rc<RefCell<BOSNode>>);

fn imax(i1: u32, i2: u32) -> u32 {
    if i1 > i2 {
        i1
    } else {
        i2
    }
}

fn bostree_balance(node: &BOSNode) -> i32 {
    let left_depth = node
        .left_child_node
        .as_ref()
        .map_or(0, |n| n.borrow().depth + 1);
    let right_depth = node
        .right_child_node
        .as_ref()
        .map_or(0, |n| n.borrow().depth + 1);
    right_depth as i32 - left_depth as i32
}

fn rotate_right(tree: &mut BOSTree, p_rc: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    let l_rc = p_rc.borrow_mut().left_child_node.clone().unwrap();
    let p_parent = l_rc.borrow().parent_node.clone();

    if let Some(ref p_parent_weak) = p_parent {
        if let Some(p_parent) = p_parent_weak.upgrade() {
            let mut pp = p_parent.borrow_mut();
            if pp.left_child_node.as_ref().map_or(false, |n| Rc::ptr_eq(n, p_rc)) {
                pp.left_child_node = Some(l_rc.clone());
            } else {
                pp.right_child_node = Some(l_rc.clone());
            }
        }
    } else {
        tree.root_node = Some(l_rc.clone());
    }

    l_rc.borrow_mut().parent_node = p_parent;

    let l_right = l_rc.borrow().right_child_node.clone();
    p_rc.borrow_mut().left_child_node = l_right.clone();
    p_rc.borrow_mut().left_child_count = l_rc.borrow().right_child_count;

    if let Some(ref l_right_rc) = l_right {
        l_right_rc.borrow_mut().parent_node = Some(Rc::downgrade(p_rc));
    }

    {
        let left_depth = p_rc
            .borrow()
            .left_child_node
            .as_ref()
            .map_or(0, |n| n.borrow().depth + 1);
        let right_depth = p_rc
            .borrow()
            .right_child_node
            .as_ref()
            .map_or(0, |n| n.borrow().depth + 1);
        p_rc.borrow_mut().depth = imax(left_depth, right_depth);
        p_rc.borrow_mut().parent_node = Some(Rc::downgrade(&l_rc));
    }

    {
        let mut l = l_rc.borrow_mut();
        l.right_child_node = Some(p_rc.clone());
        l.right_child_count = p_rc.borrow().left_child_count + p_rc.borrow().right_child_count + 1;
        let left_depth = l.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        let right_depth = l.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        l.depth = imax(left_depth, right_depth);
    }

    l_rc.clone()
}

fn rotate_left(tree: &mut BOSTree, p_rc: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    let r_rc = p_rc.borrow_mut().right_child_node.clone().unwrap();
    let p_parent = r_rc.borrow().parent_node.clone();

    if let Some(ref p_parent_weak) = p_parent {
        if let Some(p_parent) = p_parent_weak.upgrade() {
            let mut pp = p_parent.borrow_mut();
            if pp.left_child_node.as_ref().map_or(false, |n| Rc::ptr_eq(n, p_rc)) {
                pp.left_child_node = Some(r_rc.clone());
            } else {
                pp.right_child_node = Some(r_rc.clone());
            }
        }
    } else {
        tree.root_node = Some(r_rc.clone());
    }

    r_rc.borrow_mut().parent_node = p_parent;

    let r_left = r_rc.borrow().left_child_node.clone();
    p_rc.borrow_mut().right_child_node = r_left.clone();
    p_rc.borrow_mut().right_child_count = r_rc.borrow().left_child_count;

    if let Some(ref r_left_rc) = r_left {
        r_left_rc.borrow_mut().parent_node = Some(Rc::downgrade(p_rc));
    }

    {
        let left_depth = p_rc
            .borrow()
            .left_child_node
            .as_ref()
            .map_or(0, |n| n.borrow().depth + 1);
        let right_depth = p_rc
            .borrow()
            .right_child_node
            .as_ref()
            .map_or(0, |n| n.borrow().depth + 1);
        p_rc.borrow_mut().depth = imax(left_depth, right_depth);
        p_rc.borrow_mut().parent_node = Some(Rc::downgrade(&r_rc));
    }

    {
        let mut r = r_rc.borrow_mut();
        r.left_child_node = Some(p_rc.clone());
        r.left_child_count = p_rc.borrow().left_child_count + p_rc.borrow().right_child_count + 1;
        let left_depth = r.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        let right_depth = r.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
        r.depth = imax(left_depth, right_depth);
    }

    r_rc.clone()
}

impl BOSTree {
    pub fn bostree_new(
        cmp_function: BOSTreeCmpFunction,
        free_function: Option<BOSTreeFreeFunction>,
    ) -> Self {
        BOSTree {
            root_node: None,
            cmp_function,
            free_function,
        }
    }

    pub fn bostree_node_count(&self) -> u32 {
        self.root_node.as_ref().map_or(0, |root| {
            root.borrow().left_child_count + root.borrow().right_child_count + 1
        })
    }

    pub fn bostree_insert(&mut self, key: String, data: Option<String>) -> Rc<RefCell<BOSNode>> {
        let mut node_ptr: Option<&mut Option<Rc<RefCell<BOSNode>>>> = Some(&mut self.root_node);
        let mut parent_node: Option<Rc<RefCell<BOSNode>>> = None;

        while let Some(ref mut opt_rc) = node_ptr {
            if let Some(ref curr_rc) = opt_rc {
                parent_node = Some(curr_rc.clone());
                let cmp = (self.cmp_function)(&key, &curr_rc.borrow().key);
                if cmp < 0 {
                    curr_rc.borrow_mut().left_child_count += 1;
                    node_ptr = Some(&mut curr_rc.borrow_mut().left_child_node);
                } else {
                    curr_rc.borrow_mut().right_child_count += 1;
                    node_ptr = Some(&mut curr_rc.borrow_mut().right_child_node);
                }
            } else {
                break;
            }
        }

        let new_node = Rc::new(RefCell::new(BOSNode {
            left_child_count: 0,
            right_child_count: 0,
            depth: 1,
            left_child_node: None,
            right_child_node: None,
            parent_node: parent_node.as_ref().map(|p| Rc::downgrade(p)),
            key,
            data,
            weak_ref_count: 1,
            weak_ref_node_valid: 1,
        }));

        if let Some(ref mut opt_rc) = node_ptr {
            *opt_rc = Some(new_node.clone());
        }

        if parent_node.is_none() {
            return new_node;
        }

        let parent_node = parent_node.unwrap();
        let mut curr = parent_node.clone();

        if curr.borrow().left_child_node.is_some() && curr.borrow().right_child_node.is_some() {
        } else {
            curr.borrow_mut().depth += 1;
            let mut curr_weak = Rc::downgrade(&curr);
            while let Some(curr_strong) = curr_weak.upgrade() {
                let parent_opt = curr_strong.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
                if let Some(parent) = parent_opt {
                    let mut p = parent.borrow_mut();
                    let new_left_depth = p.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    let new_right_depth = p.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                    let max_depth = imax(new_left_depth, new_right_depth);

                    if p.depth != max_depth {
                        p.depth = max_depth;
                    } else {
                        break;
                    }
                    drop(p);

                    let balance = bostree_balance(&parent.borrow());
                    if new_left_depth as i32 - new_right_depth as i32 == 2 {
                        if bostree_balance(&parent.borrow().left_child_node.as_ref().unwrap().borrow()) > 0 {
                            rotate_left(self, &parent.borrow().left_child_node.as_ref().unwrap());
                        }
                        rotate_right(self, &parent);
                    } else if new_right_depth as i32 - new_left_depth as i32 == 2 {
                        if bostree_balance(&parent.borrow().right_child_node.as_ref().unwrap().borrow()) < 0 {
                            rotate_right(self, &parent.borrow().right_child_node.as_ref().unwrap());
                        }
                        rotate_left(self, &parent);
                    }

                    curr_weak = Rc::downgrade(&parent);
                } else {
                    break;
                }
            }
        }

        new_node
    }

    pub fn bostree_remove(&mut self, node: &Rc<RefCell<BOSNode>>) {
        let mut bubble_up: Option<Rc<RefCell<BOSNode>>> = None;

        let has_left = node.borrow().left_child_node.is_some();
        let has_right = node.borrow().right_child_node.is_some();

        if has_left && has_right {
            let mut candidate: Option<Rc<RefCell<BOSNode>>> = None;
            let mut lost_child: Option<Rc<RefCell<BOSNode>>> = None;

            if node.borrow().left_child_node.as_ref().map_or(0, |n| n.borrow().depth)
                >= node.borrow().right_child_node.as_ref().map_or(0, |n| n.borrow().depth)
            {
                node.borrow_mut().left_child_count -= 1;
                candidate = node.borrow().left_child_node.clone();
                while candidate.as_ref().map_or(false, |c| c.borrow().right_child_node.is_some()) {
                    candidate.as_ref().unwrap().borrow_mut().right_child_count -= 1;
                    candidate = candidate.as_ref().unwrap().borrow().right_child_node.clone();
                }
                lost_child = candidate.as_ref().unwrap().borrow().left_child_node.clone();
            } else {
                node.borrow_mut().right_child_count -= 1;
                candidate = node.borrow().right_child_node.clone();
                while candidate.as_ref().map_or(false, |c| c.borrow().left_child_node.is_some()) {
                    candidate.as_ref().unwrap().borrow_mut().left_child_count -= 1;
                    candidate = candidate.as_ref().unwrap().borrow().left_child_node.clone();
                }
                lost_child = candidate.as_ref().unwrap().borrow().right_child_node.clone();
            }

            let bubble_start = candidate.as_ref().unwrap().borrow().parent_node.as_ref().and_then(|w| w.upgrade()).unwrap();
            {
                let mut bs = bubble_start.borrow_mut();
                if bs.left_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, candidate.as_ref().unwrap())) {
                    bs.left_child_node = lost_child.clone();
                } else {
                    bs.right_child_node = lost_child.clone();
                }
                if let Some(ref lc) = lost_child {
                    lc.borrow_mut().parent_node = Some(Rc::downgrade(&bubble_start));
                }
            }

            let node_parent = node.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            if let Some(ref np) = node_parent {
                let mut np_mut = np.borrow_mut();
                if np_mut.left_child_node.as_ref().map_or(false, |n| Rc::ptr_eq(n, node)) {
                    np_mut.left_child_node = candidate.clone();
                } else {
                    np_mut.right_child_node = candidate.clone();
                }
            } else {
                self.root_node = candidate.clone();
            }

            {
                let mut c = candidate.as_ref().unwrap().borrow_mut();
                c.parent_node = node.borrow().parent_node.clone();
            }

            {
                let mut c = candidate.as_ref().unwrap().borrow_mut();
                c.left_child_node = node.borrow().left_child_node.clone();
                c.left_child_count = node.borrow().left_child_count;
                c.right_child_node = node.borrow().right_child_node.clone();
                c.right_child_count = node.borrow().right_child_count;
            }

            if let Some(ref lc) = candidate.as_ref().unwrap().borrow().left_child_node {
                lc.borrow_mut().parent_node = Some(Rc::downgrade(candidate.as_ref().unwrap()));
            }
            if let Some(ref rc) = candidate.as_ref().unwrap().borrow().right_child_node {
                rc.borrow_mut().parent_node = Some(Rc::downgrade(candidate.as_ref().unwrap()));
            }

            if !Rc::ptr_eq(&bubble_start, node) {
                let mut bubble_cur = bubble_start.clone();
                loop {
                    {
                        let mut bc = bubble_cur.borrow_mut();
                        let left_depth = bc.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                        let right_depth = bc.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                        bc.depth = imax(left_depth, right_depth);
                    }
                    let balance = bostree_balance(&bubble_cur.borrow());
                    if balance > 1 {
                        if bostree_balance(&bubble_cur.borrow().right_child_node.as_ref().unwrap().borrow()) < 0 {
                            rotate_right(self, &bubble_cur.borrow().right_child_node.as_ref().unwrap());
                        }
                        let new_bubble = rotate_left(self, &bubble_cur);
                        bubble_cur = new_bubble;
                    } else if balance < -1 {
                        if bostree_balance(&bubble_cur.borrow().left_child_node.as_ref().unwrap().borrow()) > 0 {
                            rotate_left(self, &bubble_cur.borrow().left_child_node.as_ref().unwrap());
                        }
                        let new_bubble = rotate_right(self, &bubble_cur);
                        bubble_cur = new_bubble;
                    }

                    if bubble_cur.borrow().parent_node.as_ref().and_then(|w| w.upgrade()).map_or(false, |p| Rc::ptr_eq(&p, candidate.as_ref().unwrap())) {
                        break;
                    }
                    let next_parent = bubble_cur.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
                    if next_parent.is_none() {
                        break;
                    }
                    bubble_cur = next_parent.unwrap();
                }
            }

            {
                let mut c = candidate.as_ref().unwrap().borrow_mut();
                let left_depth = c.left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                let right_depth = c.right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                c.depth = imax(left_depth, right_depth);
            }

            bubble_up = candidate.as_ref().unwrap().borrow().parent_node.clone().as_ref().and_then(|w| w.upgrade());

            if let Some(ref bu) = bubble_up {
                if bu.borrow().left_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, candidate.as_ref().unwrap())) {
                    bu.borrow_mut().left_child_count -= 1;
                } else {
                    bu.borrow_mut().right_child_count -= 1;
                }
            }
        } else {
            if node.borrow().parent_node.as_ref().and_then(|w| w.upgrade()).is_none() {
                let new_root = if node.borrow().left_child_node.is_some() {
                    node.borrow().left_child_node.clone()
                } else {
                    node.borrow().right_child_node.clone()
                };

                if let Some(ref nr) = new_root {
                    nr.borrow_mut().parent_node = None;
                }
                self.root_node = new_root;
                bubble_up = None;
            } else {
                let candidate = if node.borrow().left_child_node.is_some() {
                    node.borrow().left_child_node.clone()
                } else {
                    node.borrow().right_child_node.clone()
                };
                let candidate_count = if node.borrow().left_child_node.is_some() {
                    node.borrow().left_child_count
                } else {
                    node.borrow().right_child_count
                };

                let node_parent = node.borrow().parent_node.as_ref().and_then(|w| w.upgrade()).unwrap();
                {
                    let mut np = node_parent.borrow_mut();
                    if np.left_child_node.as_ref().map_or(false, |n| Rc::ptr_eq(n, node)) {
                        np.left_child_node = candidate.clone();
                        np.left_child_count = candidate_count;
                    } else {
                        np.right_child_node = candidate.clone();
                        np.right_child_count = candidate_count;
                    }
                }

                if let Some(ref c) = candidate {
                    c.borrow_mut().parent_node = Some(Rc::downgrade(&node_parent));
                }

                bubble_up = Some(node_parent);
            }
        }

        let mut bubbling_finished = false;
        let mut bubble_up_opt = bubble_up;
        while let Some(bubble_up_rc) = bubble_up_opt {
            if !bubbling_finished {
                let left_depth = bubble_up_rc.borrow().left_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                let right_depth = bubble_up_rc.borrow().right_child_node.as_ref().map_or(0, |n| n.borrow().depth + 1);
                let new_depth = imax(left_depth, right_depth);
                let depth_changed = new_depth != bubble_up_rc.borrow().depth;

                bubble_up_rc.borrow_mut().depth = new_depth;

                let balance = bostree_balance(&bubble_up_rc.borrow());
                if balance < -1 {
                    if bostree_balance(&bubble_up_rc.borrow().left_child_node.as_ref().unwrap().borrow()) > 0 {
                        rotate_left(self, &bubble_up_rc.borrow().left_child_node.as_ref().unwrap());
                    }
                    bubble_up_opt = Some(rotate_right(self, &bubble_up_rc));
                } else if balance > 1 {
                    if bostree_balance(&bubble_up_rc.borrow().right_child_node.as_ref().unwrap().borrow()) < 0 {
                        rotate_right(self, &bubble_up_rc.borrow().right_child_node.as_ref().unwrap());
                    }
                    bubble_up_opt = Some(rotate_left(self, &bubble_up_rc));
                } else {
                    if !depth_changed {
                        bubbling_finished = true;
                    }
                }
            }

            let parent_opt = bubble_up_rc.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            if let Some(ref parent_rc) = parent_opt {
                let mut p = parent_rc.borrow_mut();
                if p.left_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, &bubble_up_rc)) {
                    p.left_child_count -= 1;
                } else {
                    p.right_child_count -= 1;
                }
            }
            bubble_up_opt = parent_opt;
        }

        node.borrow_mut().weak_ref_node_valid = 0;
        self.bostree_node_weak_unref(node);
    }

    pub fn bostree_node_weak_unref(
        &mut self,
        node: &Rc<RefCell<BOSNode>>,
    ) -> Option<Rc<RefCell<BOSNode>>> {
        node.borrow_mut().weak_ref_count -= 1;
        if node.borrow().weak_ref_count == 0 {
            if let Some(ref free_fn) = self.free_function {
                free_fn(node);
            }
            None
        } else if node.borrow().weak_ref_node_valid == 1 {
            Some(node.clone())
        } else {
            None
        }
    }

    pub fn bostree_lookup(&self, key: &str) -> Option<Rc<RefCell<BOSNode>>> {
        let mut node = self.root_node.clone();
        while let Some(ref n) = node {
            let cmp = (self.cmp_function)(key, &n.borrow().key);
            if cmp == 0 {
                break;
            } else if cmp < 0 {
                node = n.borrow().left_child_node.clone();
            } else {
                node = n.borrow().right_child_node.clone();
            }
        }
        node
    }

    pub fn bostree_select(&self, index: u32) -> Option<Rc<RefCell<BOSNode>>> {
        let mut node = self.root_node.clone();
        let mut idx = index;
        while let Some(ref n) = node {
            if n.borrow().left_child_count <= idx {
                idx = idx - n.borrow().left_child_count;
                if idx == 0 {
                    return Some(n.clone());
                }
                idx -= 1;
                node = n.borrow().right_child_node.clone();
            } else {
                node = n.borrow().left_child_node.clone();
            }
        }
        None
    }

    #[cfg(debug_assertions)]
    pub fn bostree_print(&self) {
        fn print_helper(node: &Rc<RefCell<BOSNode>>) {
            let n = node.borrow();
            println!(
                "  {} [label=\"\\N ({},{},{})\"",
                n.key, n.left_child_count, n.right_child_count, n.depth
            );
            if let Some(ref parent_weak) = n.parent_node {
                if let Some(parent) = parent_weak.upgrade() {
                    println!("  {} -> {} [color=green];", n.key, parent.borrow().key);
                }
            }

            if let Some(ref left) = n.left_child_node {
                println!("  {} -> {}", n.key, left.borrow().key);
                print_helper(left);
            }
            if let Some(ref right) = n.right_child_node {
                println!("  {} -> {}", n.key, right.borrow().key);
                print_helper(right);
            }
        }

        if self.root_node.is_some() {
            println!("digraph {{");
            println!("  ordering = out;");
            print_helper(self.root_node.as_ref().unwrap());
            println!("}}");
        }
    }
}

pub fn bostree_node_weak_ref(node: &Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    node.borrow_mut().weak_ref_count += 1;
    node.clone()
}

pub fn bostree_next_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if node.borrow().right_child_node.is_some() {
        let mut curr = node.borrow().right_child_node.clone().unwrap();
        while curr.borrow().left_child_node.is_some() {
            curr = curr.borrow().left_child_node.clone().unwrap();
        }
        return Some(curr);
    } else if node.borrow().parent_node.as_ref().and_then(|w| w.upgrade()).is_some() {
        let mut curr = node.clone();
        loop {
            let parent_opt = curr.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            if let Some(ref parent) = parent_opt {
                if parent.borrow().right_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, &curr)) {
                    curr = parent.clone();
                } else {
                    return Some(parent.clone());
                }
            } else {
                return None;
            }
        }
    }
    None
}

pub fn bostree_previous_node(node: &Rc<RefCell<BOSNode>>) -> Option<Rc<RefCell<BOSNode>>> {
    if node.borrow().left_child_node.is_some() {
        let mut curr = node.borrow().left_child_node.clone().unwrap();
        while curr.borrow().right_child_node.is_some() {
            curr = curr.borrow().right_child_node.clone().unwrap();
        }
        return Some(curr);
    } else if node.borrow().parent_node.as_ref().and_then(|w| w.upgrade()).is_some() {
        let mut curr = node.clone();
        loop {
            let parent_opt = curr.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
            if let Some(ref parent) = parent_opt {
                if parent.borrow().left_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, &curr)) {
                    curr = parent.clone();
                } else {
                    return Some(parent.clone());
                }
            } else {
                return None;
            }
        }
    }
    None
}

pub fn bostree_rank(node: &Rc<RefCell<BOSNode>>) -> u32 {
    let mut counter = node.borrow().left_child_count;
    let mut curr = node.clone();
    loop {
        let parent_opt = curr.borrow().parent_node.as_ref().and_then(|w| w.upgrade());
        if let Some(ref parent) = parent_opt {
            if parent.borrow().right_child_node.as_ref().map_or(false, |c| Rc::ptr_eq(c, &curr)) {
                counter += 1 + parent.borrow().left_child_count;
            }
            curr = parent.clone();
        } else {
            break;
        }
    }
    counter
}

